import{_ as t,C as r,o as n,c as o,a2 as i,E as s}from"./chunks/framework.BqNd1sPY.js";const g=JSON.parse('{"title":"D08：训练数据与分词器","description":"","frontmatter":{},"headers":[],"relativePath":"01-14天理论课/D08-训练数据与分词器.md","filePath":"01-14天理论课/D08-训练数据与分词器.md"}'),l={name:"01-14天理论课/D08-训练数据与分词器.md"};function d(m,a,k,c,p,h){const e=r("MermaidDiagram");return n(),o("div",null,[a[0]||(a[0]=i('<h1 id="d08-训练数据与分词器" tabindex="-1">D08：训练数据与分词器 <a class="header-anchor" href="#d08-训练数据与分词器" aria-label="Permalink to &quot;D08：训练数据与分词器&quot;">​</a></h1><h2 id="今日目标" tabindex="-1">今日目标 <a class="header-anchor" href="#今日目标" aria-label="Permalink to &quot;今日目标&quot;">​</a></h2><p>建立“许可与目标 -&gt; 清洗 -&gt; 去重 -&gt; 切分 -&gt; <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 化 -&gt; 打包”的数据流水线意识。</p><h2 id="数据不是越多越好" tabindex="-1">数据不是越多越好 <a class="header-anchor" href="#数据不是越多越好" aria-label="Permalink to &quot;数据不是越多越好&quot;">​</a></h2><p>训练数据决定模型会反复练习什么。数量、质量、多样性、领域配比、时效、许可和隐私需要一起考虑。高比例重复、错误答案、模板垃圾或隐私信息会直接进入训练信号。</p><h2 id="推荐流水线" tabindex="-1">推荐流水线 <a class="header-anchor" href="#推荐流水线" aria-label="Permalink to &quot;推荐流水线&quot;">​</a></h2>',6)),s(e,{code:""}),a[1]||(a[1]=i(`<p>相近文档不能一份进训练集、一份进<a href="/LLMTrain/05-速查表/术语速查#term-validation-set" class="wiki-term" data-wiki-title="validation set" data-wiki-summary="不参与梯度更新、用于选择配置和观察泛化表现的数据。" data-wiki-misconception="反复针对验证集调参不会产生信息泄漏。">验证集</a>，否则验证结果会虚高。切分应尊重文档、会话或用户边界，避免把同一对象拆散后泄漏。</p><h2 id="因果语言模型的标签" tabindex="-1">因果语言模型的标签 <a class="header-anchor" href="#因果语言模型的标签" aria-label="Permalink to &quot;因果语言模型的标签&quot;">​</a></h2><p>序列是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入：今 天 天</span></span>
<span class="line"><span>目标：天 天 气</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>每个位置预测它后面的 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a>。实现中常用同一序列错开一位；padding 或不应计分的位置会被 mask 掉。</p><h2 id="分词器取舍" tabindex="-1">分词器取舍 <a class="header-anchor" href="#分词器取舍" aria-label="Permalink to &quot;分词器取舍&quot;">​</a></h2><ul><li><strong>字符级</strong>：概念简单，<a href="/LLMTrain/05-速查表/术语速查#term-vocab" class="wiki-term" data-wiki-title="vocab" data-wiki-summary="tokenizer 可以表示的 token 集合；输出层通常也对这组 token 给出分数。" data-wiki-misconception="词表包含了模型掌握的全部知识。">词表</a>小，但序列通常较长。本课程项目使用它。</li><li><strong>BPE 类方法</strong>：反复合并常见相邻单元，常用于子词或字节级方案。</li><li><strong>Unigram</strong>：从候选子词集合中选择概率模型支持的切分。</li><li><strong>SentencePiece</strong>：一个 <a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">tokenizer</a> 工具包，支持 BPE 和 Unigram；它不是单独一种与二者并列的切分原理。</li></ul><p>不同 <a href="/LLMTrain/05-速查表/术语速查#term-tokenizer" class="wiki-term" data-wiki-title="tokenizer" data-wiki-summary="负责把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表。" data-wiki-misconception="tokenizer 是模型自己临时决定的切词方式。">tokenizer</a> 下的 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 数和困惑度不可直接混为同一尺度。</p><h2 id="数据质检清单" tabindex="-1">数据质检清单 <a class="header-anchor" href="#数据质检清单" aria-label="Permalink to &quot;数据质检清单&quot;">​</a></h2><ul><li>[ ] 有权使用和再分发数据。</li><li>[ ] 抽样查看原文，不只看统计。</li><li>[ ] 记录语种、长度、重复率和异常字符。</li><li>[ ] 检查个人信息、密钥和危险内容。</li><li>[ ] 训练与验证没有文档级或近重复泄漏。</li><li>[ ] <a href="/LLMTrain/05-速查表/术语速查#term-validation-set" class="wiki-term" data-wiki-title="validation set" data-wiki-summary="不参与梯度更新、用于选择配置和观察泛化表现的数据。" data-wiki-misconception="反复针对验证集调参不会产生信息泄漏。">验证集</a>未参与规则和超<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>的反复调优。</li></ul><h2 id="今日验收" tabindex="-1">今日验收 <a class="header-anchor" href="#今日验收" aria-label="Permalink to &quot;今日验收&quot;">​</a></h2><p>解释为什么“随机按行切分”可能泄漏；再为聊天数据列出三个应按会话而不是按消息切分的理由。</p><p>来源：<a href="https://arxiv.org/abs/1808.06226" target="_blank" rel="noreferrer">SentencePiece</a></p><p>下一课：<a href="./D09-一次完整训练循环">D09：一次完整训练循环</a></p>`,14))])}const _=t(l,[["render",d]]);export{g as __pageData,_ as default};
